import Database from "better-sqlite3";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import type { AgentEvent } from "../../shared/events.ts";

export type NewEvent = Omit<AgentEvent, "id">;

export function openDb(path: string) {
  mkdirSync(dirname(path), { recursive: true });
  const db = new Database(path);
  db.pragma("journal_mode = WAL");
  db.exec(`
    CREATE TABLE IF NOT EXISTS events (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      ts INTEGER NOT NULL,
      client_ts INTEGER,
      run_id TEXT NOT NULL,
      session_id TEXT NOT NULL,
      agent_id TEXT NOT NULL,
      parent_agent_id TEXT,
      kind TEXT NOT NULL,
      source TEXT NOT NULL,
      payload TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS events_run ON events (run_id, seq);
  `);

  const insert = db.prepare(`
    INSERT INTO events (ts, client_ts, run_id, session_id, agent_id, parent_agent_id, kind, source, payload)
    VALUES (@ts, @client_ts, @run_id, @session_id, @agent_id, @parent_agent_id, @kind, @source, @payload)
  `);
  const byRun = db.prepare(`SELECT * FROM events WHERE run_id = ? AND seq > ? ORDER BY seq`);
  const runs = db.prepare(`
    SELECT run_id, MIN(ts) AS started, MAX(ts) AS last, COUNT(*) AS events,
           COUNT(DISTINCT agent_id) AS agents
    FROM events GROUP BY run_id ORDER BY started DESC
  `);

  const toEvent = (row: any): AgentEvent => ({
    id: String(row.seq),
    ts: row.ts,
    client_ts: row.client_ts ?? undefined,
    run_id: row.run_id,
    session_id: row.session_id,
    agent_id: row.agent_id,
    parent_agent_id: row.parent_agent_id ?? undefined,
    kind: row.kind,
    source: row.source,
    payload: JSON.parse(row.payload),
  });

  return {
    append(e: NewEvent): AgentEvent {
      const info = insert.run({
        ...e,
        client_ts: e.client_ts ?? null,
        parent_agent_id: e.parent_agent_id ?? null,
        payload: JSON.stringify(e.payload),
      });
      return { ...e, id: String(info.lastInsertRowid) };
    },
    events(runId: string, afterSeq = 0): AgentEvent[] {
      return byRun.all(runId, afterSeq).map(toEvent);
    },
    runs() {
      return runs.all();
    },
  };
}

export type Db = ReturnType<typeof openDb>;

import { SPAWN_TOOLS, type EventKind } from "../../shared/events.ts";
import type { NewEvent } from "./db.ts";

// Raw hook input as Claude Code sends it on stdin. Only the fields we read are typed.
export interface HookInput {
  hook_event_name: string;
  session_id: string;
  transcript_path?: string;
  cwd?: string;
  agent_id?: string;
  agent_type?: string;
  tool_name?: string;
  tool_use_id?: string;
  tool_input?: Record<string, unknown>;
  tool_response?: unknown;
  agent_transcript_path?: string;
  [k: string]: unknown;
}

export function isHookInput(x: unknown): x is HookInput {
  return (
    typeof x === "object" && x !== null &&
    typeof (x as any).hook_event_name === "string" &&
    typeof (x as any).session_id === "string"
  );
}

function kindFor(h: HookInput): EventKind {
  switch (h.hook_event_name) {
    case "SessionStart":
    case "SubagentStart":
      return "session_start";
    case "SessionEnd":
    case "SubagentStop":
      return "session_end";
    case "UserPromptSubmit":
      return "turn_start";
    case "Stop":
    case "StopFailure":
      return "turn_end";
    case "PreToolUse":
      return SPAWN_TOOLS.has(h.tool_name ?? "") ? "spawn" : "tool_start";
    case "PostToolUse":
    case "PostToolUseFailure":
      return "tool_end";
    case "PermissionRequest":
      return "permission_wait";
    default:
      return "other";
  }
}

// SubagentStart/SubagentStop describe the subagent itself, so agent_id is the lane.
// Every other event's agent_id (when present) is the subagent the event came from.
export function normalizeHook(h: HookInput, ts: number): NewEvent {
  return {
    ts,
    run_id: h.session_id,
    session_id: h.session_id,
    agent_id: h.agent_id ?? h.session_id,
    kind: kindFor(h),
    source: "hook",
    payload: h,
  };
}

import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { openDb } from "./db.ts";
import { isHookInput, normalizeHook } from "./normalize.ts";
import { createCorrelator } from "./correlate.ts";

const PORT = Number(process.env.SWARMTRACER_PORT ?? 47821);
const DB_PATH = process.env.SWARMTRACER_DB ?? fileURLToPath(new URL("../../data/swarmtracer.db", import.meta.url));
const VERBOSE = process.env.SWARMTRACER_VERBOSE === "1";

const db = openDb(DB_PATH);
const correlator = createCorrelator(db, (msg) => console.log(`[correlate] ${msg}`));
const indexHtml = readFileSync(new URL("../static/index.html", import.meta.url));

function ingest(body: unknown, ts: number) {
  for (const item of Array.isArray(body) ? body : [body]) {
    if (!isHookInput(item)) continue; // CLI events arrive in M4
    db.append(normalizeHook(item, ts));
    correlator.observe(item);
    if (VERBOSE) console.log(`[event] ${item.hook_event_name} ${item.agent_id ?? "root"} ${item.tool_name ?? ""}`);
  }
}

function json(res: ServerResponse, value: unknown) {
  res.writeHead(200, { "content-type": "application/json" });
  res.end(JSON.stringify(value));
}

function onEvents(req: IncomingMessage, res: ServerResponse) {
  const ts = Date.now(); // stamp on receipt, before reading the body
  const chunks: Buffer[] = [];
  req.on("data", (c) => chunks.push(c));
  req.on("end", () => {
    // Answer first: hooks wait on this response.
    res.writeHead(204).end();
    try {
      ingest(JSON.parse(Buffer.concat(chunks).toString("utf8")), ts);
    } catch (err) {
      console.error("[ingest] bad body:", (err as Error).message);
    }
  });
}

const server = createServer((req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const runMatch = url.pathname.match(/^\/runs\/([^/]+)\/events$/);

  if (req.method === "POST" && url.pathname === "/events") return onEvents(req, res);
  if (req.method === "GET" && url.pathname === "/runs") return json(res, db.runs());
  if (req.method === "GET" && runMatch) {
    return json(res, db.events(decodeURIComponent(runMatch[1]), Number(url.searchParams.get("after") ?? 0)));
  }
  if (req.method === "GET" && url.pathname === "/") {
    res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
    return res.end(indexHtml);
  }
  res.writeHead(404).end();
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`swarmtracer listening on http://127.0.0.1:${PORT} (db: ${DB_PATH})`);
});

import { readFile } from "node:fs/promises";
import { SPAWN_TOOLS } from "../../shared/events.ts";
import type { Db } from "./db.ts";
import type { HookInput } from "./normalize.ts";

// Links each subagent lane to the Agent tool call that spawned it.
//
// Primary: Claude Code writes <session transcript dir>/subagents/agent-<agent_id>.meta.json
// with the spawning call's `toolUseId`, which matches PreToolUse.tool_use_id in the parent.
// Confirmation/fallback: the Agent tool's PostToolUse carries tool_response.agentId.
// Last resort: if exactly one spawn in the session is unclaimed, take it.

type Method = "meta" | "tool_response" | "heuristic";

interface Spawn { parentAgentId: string; sessionId: string; childAgentId?: string }

const RETRY_MS = [0, 25, 50, 100, 200, 400, 800, 1600];

export function createCorrelator(db: Db, onLink: (msg: string) => void = () => {}) {
  const spawns = new Map<string, Spawn>(); // tool_use_id → spawn
  const linked = new Map<string, string>(); // child agent_id → tool_use_id

  function link(childAgentId: string, toolUseId: string, method: Method) {
    const spawn = spawns.get(toolUseId);
    if (!spawn) return false;
    const prior = linked.get(childAgentId);
    if (prior) {
      onLink(prior === toolUseId
        ? `confirm ${childAgentId} via ${method}`
        : `MISMATCH child=${childAgentId} ${prior} vs ${toolUseId} (${method})`);
      return true;
    }
    if (spawn.childAgentId && spawn.childAgentId !== childAgentId) {
      onLink(`MISMATCH spawn=${toolUseId} already has ${spawn.childAgentId}, got ${childAgentId} (${method})`);
      return false;
    }
    spawn.childAgentId = childAgentId;
    linked.set(childAgentId, toolUseId);
    db.append({
      ts: Date.now(),
      run_id: spawn.sessionId,
      session_id: spawn.sessionId,
      agent_id: childAgentId,
      parent_agent_id: spawn.parentAgentId,
      kind: "link",
      source: "server",
      payload: { tool_use_id: toolUseId, method },
    });
    onLink(`link ${spawn.parentAgentId} → ${childAgentId} via ${method}`);
    return true;
  }

  async function readMetaToolUseId(h: HookInput): Promise<string | undefined> {
    if (!h.transcript_path || !h.agent_id) return;
    const dir = h.transcript_path.replace(/\.jsonl$/, "");
    try {
      const meta = JSON.parse(await readFile(`${dir}/subagents/agent-${h.agent_id}.meta.json`, "utf8"));
      return typeof meta.toolUseId === "string" ? meta.toolUseId : undefined;
    } catch {
      return;
    }
  }

  async function onSubagentStart(h: HookInput) {
    const child = h.agent_id!;
    // Read meta even when tool_response already linked the child: link() then reports confirm/MISMATCH.
    for (const delay of RETRY_MS) {
      if (delay) await new Promise((r) => setTimeout(r, delay));
      const id = await readMetaToolUseId(h);
      if (id && link(child, id, "meta")) return;
    }
    // No meta file. A foreground child's agentId only reaches PostToolUse when it finishes,
    // so guess now to get a live link; a later tool_response link reports any MISMATCH.
    if (linked.has(child)) return;
    const open = [...spawns.entries()].filter(([, s]) => s.sessionId === h.session_id && !s.childAgentId);
    if (open.length === 1) link(child, open[0][0], "heuristic");
    else onLink(`UNLINKED child=${child} (${open.length} open spawns)`);
  }

  return {
    observe(h: HookInput) {
      if (h.hook_event_name === "PreToolUse" && SPAWN_TOOLS.has(h.tool_name ?? "") && h.tool_use_id) {
        spawns.set(h.tool_use_id, { parentAgentId: h.agent_id ?? h.session_id, sessionId: h.session_id });
      } else if (h.hook_event_name === "SubagentStart" && h.agent_id) {
        void onSubagentStart(h);
      } else if (
        (h.hook_event_name === "PostToolUse" || h.hook_event_name === "PostToolUseFailure") &&
        SPAWN_TOOLS.has(h.tool_name ?? "") && h.tool_use_id
      ) {
        const agentId = (h.tool_response as any)?.agentId;
        if (typeof agentId === "string") link(agentId, h.tool_use_id, "tool_response");
      }
    },
  };
}

#!/usr/bin/env node
// Prints a Claude Code settings snippet that registers the adapter on every event SwarmTracer reads.
// Paste the output into a project's .claude/settings.json (or pass it to `claude --settings`).
import { fileURLToPath } from "node:url";

const adapter = fileURLToPath(new URL("./adapter.sh", import.meta.url));
const EVENTS = [
  "SessionStart", "SessionEnd", "UserPromptSubmit", "Stop", "StopFailure",
  "PreToolUse", "PostToolUse", "PostToolUseFailure", "PermissionRequest",
  "SubagentStart", "SubagentStop",
];

const hook = { type: "command", command: JSON.stringify(adapter), timeout: 5 };
const hooks = Object.fromEntries(EVENTS.map((e) => [e, [{ hooks: [hook] }]]));
console.log(JSON.stringify({ hooks }, null, 2));

// Checks an M0 spike run: every event arrived, every child is linked to the right spawn,
// and the server-down run behaved like a normal run.
import { readFileSync } from "node:fs";

const [eventsPath, upPath, downPath, downStderr, serverLog] = process.argv.slice(2);
const events = JSON.parse(readFileSync(eventsPath, "utf8"));
const ok = (cond, msg) => console.log(`${cond ? "PASS" : "FAIL"}  ${msg}`);

const root = events[0]?.session_id;
const hook = (name) => events.filter((e) => e.payload.hook_event_name === name);
const spawns = hook("PreToolUse").filter((e) => e.payload.tool_name === "Agent");
const starts = hook("SubagentStart");
const stops = hook("SubagentStop");
const links = events.filter((e) => e.kind === "link");

console.log(`\n== verification (${events.length} events, run ${root})`);
const counts = {};
for (const e of events) counts[e.payload.hook_event_name ?? e.kind] = (counts[e.payload.hook_event_name ?? e.kind] ?? 0) + 1;
console.log(counts);

ok(hook("SessionStart").length === 1 && hook("SessionEnd").length === 1, "one SessionStart and one SessionEnd");
ok(spawns.length === 3 && starts.length === 3 && stops.length === 3, `3 spawns / starts / stops (got ${spawns.length}/${starts.length}/${stops.length})`);

const spawnTs = spawns.map((e) => e.ts), startTs = starts.map((e) => e.ts);
ok(Math.max(...spawnTs) < Math.min(...startTs) + 5000, "spawns were parallel (all PreToolUse before children ran long)");

for (const pre of hook("PreToolUse")) {
  const post = events.find((e) => e.payload.tool_use_id === pre.payload.tool_use_id && e.kind === "tool_end");
  if (!post) ok(false, `PreToolUse ${pre.payload.tool_name} ${pre.payload.tool_use_id} has a matching PostToolUse`);
}
ok(true, "checked Pre/Post pairing (failures listed above, if any)");

for (const s of starts) {
  const childId = s.payload.agent_id;
  const childLinks = links.filter((l) => l.agent_id === childId);
  const methods = childLinks.map((l) => l.payload.method);
  const spawn = spawns.find((p) => p.payload.tool_use_id === childLinks[0]?.payload.tool_use_id);
  // Ground truth: the PostToolUse for the Agent call names the agentId it ran.
  const post = events.find((e) => e.payload.hook_event_name === "PostToolUse" && e.payload.tool_use_id === spawn?.payload.tool_use_id);
  const truth = post?.payload.tool_response?.agentId;
  ok(childLinks.length === 1 && truth === childId,
    `child ${childId} (${spawn?.payload.tool_input?.description}) linked via [${methods}] at +${childLinks[0] ? childLinks[0].ts - s.ts : "?"}ms after SubagentStart; tool_response.agentId=${truth}`);
  const childEvents = events.filter((e) => e.agent_id === childId && e.kind === "tool_start");
  ok(childEvents.length >= 2, `child ${childId} tool events tagged with its agent_id (${childEvents.length} tool_start)`);
}

const log = readFileSync(serverLog, "utf8");
ok(!/MISMATCH|UNLINKED/.test(log), "correlation sources agree (no MISMATCH/UNLINKED in server log)");
const firstMethod = Object.fromEntries(links.map((l) => [l.agent_id, l.payload.method]));
const metaConfirms = (log.match(/confirm \S+ via meta|via meta/g) ?? []).length;
ok(metaConfirms === 3, `meta file resolved all 3 children (${metaConfirms}); first link methods: ${JSON.stringify(Object.values(firstMethod))}`);
const bg = spawns.map((p) => events.find((e) => e.kind === "tool_end" && e.payload.tool_use_id === p.payload.tool_use_id)?.payload.tool_response?.status);
console.log(`-- Agent call statuses: ${JSON.stringify(bg)}`);

const envOut = hook("PostToolUse").filter((e) => e.agent_id !== root && String(e.payload.tool_input?.command ?? "").startsWith("env"));
console.log("\n-- env visible to a subagent's Bash:");
console.log(envOut[0]?.payload.tool_response?.stdout ?? JSON.stringify(envOut[0]?.payload.tool_response));
console.log("-- that subagent's agent_id:", envOut[0]?.agent_id, " session_id:", envOut[0]?.session_id);

const up = JSON.parse(readFileSync(upPath, "utf8"));
let down; try { down = JSON.parse(readFileSync(downPath, "utf8")); } catch { down = null; }
const stderr = readFileSync(downStderr, "utf8");
console.log("\n-- server-down run");
ok(up.is_error === false, `server-up run succeeded: ${JSON.stringify(up.result).slice(0, 60)}, ${up.duration_ms}ms`);
ok(down && down.is_error === false, `server-down run succeeded: ${JSON.stringify(down?.result).slice(0, 60)}, ${down?.duration_ms}ms`);
ok(!/hook/i.test(stderr), `server-down stderr has no hook errors (${stderr.length} bytes)`);
